insert into public.email_templates (key, name, subject, heading, body, button_label, button_url, is_active)
values ($cl$profile-personalize$cl$, $cl$Personalizá tu perfil — primer email$cl$, $cl${{name}}, así se ve tu publicación con tu foto$cl$, $cl$Que los compradores sepan quién sos$cl$, $cl$>> Tu foto y tu nombre en 2 minutos: así trabajan los agentes en Estados Unidos.

Hola {{name}}: en Estados Unidos ningún agente publica sin su foto, porque el comprador quiere ver con quién va a hablar antes de escribir. Casa-Libre trae esa experiencia a {{country_name}}: agregá tu foto y tu nombre en 2 minutos.

![Tu publicación sin foto y con tu foto](https://casa-libre.com.py/api/media/email-assets/profile-mock-v1.jpg)$cl$, $cl$Agregar mi foto$cl$, $cl${{settings_url}}$cl$, true)
on conflict (key) do update set name = excluded.name, subject = excluded.subject, heading = excluded.heading,
  body = excluded.body, button_label = excluded.button_label, button_url = excluded.button_url, updated_at = now();
