-- 3. The newsletter automation (OFF). The admin's Automations page edits day / hour / rotation.
insert into public.automations (id, enabled, wait_days, free_tiers, updated_at)
select 'weekly_newsletter', false, 0, jsonb_build_array(jsonb_build_object(
  'day', 2, 'hour', 10, 'next', 0,
  'rotation', coalesce((
    select jsonb_agg(jsonb_build_object('template_id', t.id, 'audience', v.aud) order by v.ord)
    from (values
    ('newsletter-que-buscan-los-compradores', 'everyone', 1),
    ('newsletter-publicaciones-directas', 'never_listed', 2),
    ('newsletter-alquileres', 'everyone', 3),
    ('newsletter-historia-comision', 'everyone', 4),
    ('newsletter-fotos', 'sellers', 5),
    ('newsletter-zonas-mas-buscadas', 'everyone', 6),
    ('newsletter-tu-cuenta-esta-lista', 'never_listed', 7),
    ('newsletter-historia-inmobiliaria', 'sellers', 8),
    ('newsletter-experiencia-estados-unidos', 'everyone', 9)
    ) as v(k, aud, ord)
    join public.email_templates t on t.key = v.k
  ), '[]'::jsonb))), now()
on conflict (id) do nothing;

